/**
 * Delivery-layer end-to-end: REAL nodemailer over a REAL TLS SMTP sink.
 *
 * The mocked-email suites pin behavior when the provider call fails or succeeds; this one proves
 * the production transport itself works: the message a real SMTP relay receives carries a
 * one-time link whose token matches the stored SHA-256 digest, the token completes the reset
 * exactly once, and a genuinely unreachable relay burns the token while releasing the retry
 * cooldown (no silent 15-minute dead end).
 *
 * The sink speaks implicit TLS with an ephemeral self-signed CA generated by openssl at test
 * time (never committed); PASSWORD_RESET_SMTP_CA pins that CA, dogfooding the trust option that
 * private-relay deployments need.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
import { createHash, X509Certificate } from "node:crypto";
import { execFileSync } from "node:child_process";
import * as fs from "node:fs";
import * as net from "node:net";
import * as os from "node:os";
import * as path from "node:path";
import * as tls from "node:tls";

const mocks = vi.hoisted(() => {
  const state: any = {
    user: null as any,
    token: null as any,
  };
  state.prisma = {
    user: {
      findUnique: vi.fn(async ({ where }: any) => {
        if (where.email) return state.user?.email === where.email ? { id: state.user.id, email: state.user.email } : null;
        return state.user?.id === where.id ? { ...state.user } : null;
      }),
      updateMany: vi.fn(async ({ where, data }: any) => {
        if (!state.user || state.user.id !== where.id) return { count: 0 };
        if (where.OR) {
          const current = state.user.passwordResetRequestedAt;
          const allowed = where.OR.some((condition: any) =>
            condition.passwordResetRequestedAt === null
              ? current === null
              : current instanceof Date && current <= condition.passwordResetRequestedAt.lte,
          );
          if (!allowed) return { count: 0 };
        } else if ("passwordResetRequestedAt" in where) {
          const current = state.user.passwordResetRequestedAt;
          const expected = where.passwordResetRequestedAt;
          if (!(current instanceof Date && expected instanceof Date && current.getTime() === expected.getTime())) {
            return { count: 0 };
          }
        }
        Object.assign(state.user, data);
        return { count: 1 };
      }),
      update: vi.fn(async ({ where, data }: any) => {
        if (!state.user || state.user.id !== where.id) throw new Error("user not found");
        if (data.passwordHash !== undefined) state.user.passwordHash = data.passwordHash;
        if (data.sessionVersion?.increment) state.user.sessionVersion += data.sessionVersion.increment;
        return { id: state.user.id };
      }),
    },
    passwordResetToken: {
      upsert: vi.fn(async ({ where, create, update }: any) => {
        state.token = state.token?.userId === where.userId
          ? { ...state.token, ...update }
          : { id: "reset-token-row", ...create, usedAt: null, createdAt: new Date() };
        return state.token;
      }),
      findUnique: vi.fn(async ({ where }: any) => state.token?.tokenHash === where.tokenHash ? { ...state.token } : null),
      updateMany: vi.fn(async ({ where, data }: any) => {
        const token = state.token;
        if (!token || (where.id !== undefined && token.id !== where.id)) return { count: 0 };
        if (where.userId && token.userId !== where.userId) return { count: 0 };
        if (where.tokenHash && token.tokenHash !== where.tokenHash) return { count: 0 };
        if (where.usedAt === null && token.usedAt !== null) return { count: 0 };
        Object.assign(token, data);
        return { count: 1 };
      }),
    },
  };
  state.prisma.$transaction = vi.fn(async (callback: (client: any) => Promise<unknown>) => callback(state.prisma));
  return state;
});

vi.mock("@/lib/db", () => ({ default: mocks.prisma }));

import { requestPasswordReset, completePasswordReset, PASSWORD_RESET_TTL_MS } from "@/lib/password-reset";

// ---- Ephemeral TLS SMTP sink ---------------------------------------------------------------------

type Sink = { port: number; messages: string[]; close: () => Promise<void> };

function startSmtpSink(credentials: { key: string; cert: string }): Promise<Sink> {
  const messages: string[] = [];
  const sockets = new Set<net.Socket>();
  const server = tls.createServer({ key: credentials.key, cert: credentials.cert }, (socket) => {
    sockets.add(socket);
    let buffer = "";
    let inData = false;
    let data = "";
    socket.on("error", () => undefined);
    socket.on("close", () => sockets.delete(socket));
    socket.write("220 smtp.test ESMTP\r\n");
    socket.on("data", (chunk) => {
      buffer += chunk.toString("utf8");
      let index: number;
      while ((index = buffer.indexOf("\r\n")) !== -1) {
        const line = buffer.slice(0, index);
        buffer = buffer.slice(index + 2);
        if (inData) {
          if (line === ".") {
            inData = false;
            messages.push(data);
            data = "";
            socket.write("250 2.0.0 Ok: queued\r\n");
          } else {
            data += `${line}\r\n`;
          }
          continue;
        }
        const command = line.toUpperCase();
        if (command.startsWith("EHLO")) socket.write("250-smtp.test\r\n250 SIZE 33554432\r\n");
        else if (command.startsWith("HELO")) socket.write("250 smtp.test\r\n");
        else if (command.startsWith("MAIL FROM") || command.startsWith("RCPT TO")) socket.write("250 2.1.0 Ok\r\n");
        else if (command.startsWith("DATA")) { inData = true; socket.write("354 End data with <CR><LF>.<CR><LF>\r\n"); }
        else if (command.startsWith("QUIT")) { socket.write("221 2.0.0 Bye\r\n"); socket.end(); }
        else if (command.startsWith("RSET")) socket.write("250 2.0.0 Ok\r\n");
        else if (command.startsWith("NOOP")) socket.write("250 2.0.0 Ok\r\n");
        else socket.write("502 5.5.2 Not implemented\r\n");
      }
    });
  });
  return new Promise((resolve) => {
    server.listen(0, "127.0.0.1", () => {
      const address = server.address() as net.AddressInfo;
      resolve({
        port: address.port,
        messages,
        close: () => new Promise<void>((done) => {
          for (const socket of sockets) socket.destroy();
          server.close(() => done());
        }),
      });
    });
  });
}

// ---- Ephemeral CA + server certificate (openssl at runtime; nothing committed) ---------------------

function generateCertificates(): { caPem: string; key: string; cert: string } {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "jata-smtp-tls-"));
  const extFile = path.join(dir, "ext.cnf");
  fs.writeFileSync(extFile, "subjectAltName=DNS:localhost,IP:127.0.0.1\n");
  execFileSync("openssl", ["req", "-x509", "-newkey", "rsa:2048", "-nodes", "-days", "2",
    "-keyout", path.join(dir, "ca.key"), "-out", path.join(dir, "ca.pem"),
    "-subj", "/CN=JATA Test SMTP CA"], { stdio: "ignore" });
  execFileSync("openssl", ["req", "-newkey", "rsa:2048", "-nodes", "-days", "2",
    "-keyout", path.join(dir, "server.key"), "-out", path.join(dir, "server.csr"),
    "-subj", "/CN=localhost"], { stdio: "ignore" });
  execFileSync("openssl", ["x509", "-req", "-days", "2",
    "-in", path.join(dir, "server.csr"), "-CA", path.join(dir, "ca.pem"), "-CAkey", path.join(dir, "ca.key"),
    "-CAcreateserial", "-out", path.join(dir, "server.pem"), "-extfile", extFile], { stdio: "ignore" });
  return {
    caPem: fs.readFileSync(path.join(dir, "ca.pem"), "utf8"),
    key: fs.readFileSync(path.join(dir, "server.key"), "utf8"),
    cert: fs.readFileSync(path.join(dir, "server.pem"), "utf8"),
  };
}

function extractToken(message: string): string {
  const match = normaliseQuotedPrintable(message).match(/reset-password#token=([A-Za-z0-9_-]{43})/);
  if (!match) throw new Error("no one-time token found in the delivered message");
  return match[1];
}

/** Undo quoted-printable encoding (soft line breaks and =XX escapes) so wrapped links parse. */
function normaliseQuotedPrintable(message: string): string {
  return message
    .replace(/=\r\n/g, "")
    .replace(/=\n/g, "")
    .replace(/=([0-9A-Fa-f]{2})/g, (_match, hex: string) => String.fromCharCode(parseInt(hex, 16)));
}

describe("password reset delivery over a real TLS SMTP transport", () => {
  let certs: { caPem: string; key: string; cert: string };
  let sink: Sink;

  beforeAll(async () => {
    certs = generateCertificates();
    sink = await startSmtpSink(certs);
  }, 30_000);

  afterAll(async () => {
    await sink?.close();
  });

  afterEach(() => {
    vi.unstubAllEnvs();
    vi.restoreAllMocks();
  });

  it("delivers a one-time link whose token matches the stored digest and completes exactly once", async () => {
    vi.stubEnv("PASSWORD_RESET_SMTP_URL", `smtps://localhost:${sink.port}`);
    vi.stubEnv("PASSWORD_RESET_FROM", "JATA Test <reset@test.invalid>");
    vi.stubEnv("PASSWORD_RESET_SMTP_CA", certs.caPem);
    vi.stubEnv("PUBLIC_BASE_URL", "https://jata.example.test");
    vi.stubEnv("VERCEL_ENV", "");
    vi.stubEnv("NEXTAUTH_URL", "");
    vi.stubEnv("NODE_ENV", "production");

    // Guard: the pinned bundle must actually be a certificate, so this test can never silently
    // fall back to platform trust and pass for the wrong reason.
    expect(() => new X509Certificate(certs.caPem)).not.toThrow();

    mocks.user = { id: "user-delivery", email: "owner@example.test", passwordResetRequestedAt: null, sessionVersion: 0, passwordHash: "old" };
    mocks.token = null;

    await requestPasswordReset("owner@example.test");

    expect(sink.messages).toHaveLength(1);
    const message = sink.messages[0];
    expect(message).toContain("To: owner@example.test");
    expect(message).toContain("From: JATA Test");

    const rawToken = extractToken(message);
    const flat = normaliseQuotedPrintable(message);
    expect(rawToken).toMatch(/^[A-Za-z0-9_-]{43}$/);
    expect(flat).toContain(`https://jata.example.test/reset-password#token=${rawToken}`);
    expect(flat).toContain("one-time link");

    // The delivered token is exactly the one whose digest is at rest.
    expect(mocks.token.tokenHash).toBe(createHash("sha256").update(rawToken).digest("hex"));
    expect(mocks.token.expiresAt.getTime()).toBeGreaterThan(Date.now());
    expect(mocks.token.expiresAt.getTime()).toBeLessThanOrEqual(Date.now() + PASSWORD_RESET_TTL_MS);

    // Completing with the delivered token works once; the replay is refused.
    const userId = await completePasswordReset(rawToken, "brand-new-correct-horse");
    expect(userId).toBe("user-delivery");
    expect(mocks.token.usedAt).toBeInstanceOf(Date);
    expect(await completePasswordReset(rawToken, "another-correct-horse")).toBeNull();
    expect(mocks.user.sessionVersion).toBe(1);
  }, 30_000);

  it("burns the token and releases the retry cooldown when the relay is unreachable", async () => {
    vi.stubEnv("PASSWORD_RESET_SMTP_URL", "smtps://localhost:1");
    vi.stubEnv("PASSWORD_RESET_FROM", "JATA Test <reset@test.invalid>");
    vi.stubEnv("PUBLIC_BASE_URL", "https://jata.example.test");
    vi.stubEnv("NODE_ENV", "production");

    mocks.user = { id: "user-delivery-2", email: "owner2@example.test", passwordResetRequestedAt: null, sessionVersion: 0, passwordHash: "old" };
    mocks.token = null;
    const errorSpy = vi.spyOn(console, "error").mockImplementation(() => undefined);

    await requestPasswordReset("owner2@example.test");

    expect(sink.messages).toHaveLength(1); // the previous test's message only
    expect(mocks.token.usedAt).toBeInstanceOf(Date);
    expect(mocks.user.passwordResetRequestedAt).toBeNull();
    expect(errorSpy).toHaveBeenCalledWith("Password reset email delivery failed; recovery token invalidated.");
  }, 30_000);
});
